const crypto = require('crypto');
const headers = $json.headers || {};
const payload = $json.body || {};
const timestamp = String(headers['x-workflow-timestamp'] || '');
const nonce = String(headers['x-workflow-nonce'] || '');
const received = String(headers['x-workflow-signature'] || '');
const sourcePath = '/webhook/research-v1';
const body = JSON.stringify(payload);
const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', sourcePath, digest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const previousSecret = $env.WORKFLOW_HMAC_PREVIOUS_SECRET;
if (!secret || !timestamp || !nonce || !received) throw new Error('Workflow signature is missing');
const authentic = [secret, previousSecret].filter(Boolean).some((candidate) => {
  const expected = `sha256=${crypto.createHmac('sha256', candidate).update(canonical, 'utf8').digest('hex')}`;
  return received.length === expected.length && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
});
if (!authentic) throw new Error('Workflow signature is invalid');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Workflow signature expired');
if (payload.contractVersion !== '1.0' || !payload.correlationId || !payload.idempotencyKey || !payload.actorId || !payload.brandId || !payload.opportunityId || !payload.requestedAt) throw new Error('Research contract is invalid');
const targetPath = '/api/internal/workflows/recovery/execute';
const recoveryPayload = {
  contractVersion: '1.0',
  workflowExecutionId: String($execution.id),
  workflowName: 'WF-05 Research',
  target: 'research',
  requestPayload: payload,
};
const recoveryBody = JSON.stringify(recoveryPayload);
const nextTimestamp = String(Math.floor(Date.now() / 1000));
const nextNonce = crypto.randomUUID();
const nextDigest = crypto.createHash('sha256').update(recoveryBody, 'utf8').digest('hex');
const nextCanonical = [nextTimestamp, nextNonce, 'POST', targetPath, nextDigest].join('\n');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(nextCanonical, 'utf8').digest('hex')}`;
return [{ json: { body: recoveryBody, nonce: nextNonce, signature, timestamp: nextTimestamp, url: `${$env.APP_BASE_URL}${targetPath}` } }];

const crypto = require('crypto');
const research = $input.first().json.data;
const request = $('Signed Research Webhook').first().json.body;
if (research?.contractVersion !== '1.0' || !research.researchRunId || !research.generationRunId || typeof research.readyForWriting !== 'boolean') throw new Error('Research result contract is invalid');
if (!research.readyForWriting) return [];
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.N8N_WEBHOOK_BASE_URL;
if (!secret || !baseUrl) throw new Error('Editorial preparation environment is not configured');
const path = '/webhook/editorial-generation-v1';
const styles = ['newsworthy_authority', 'educational_breakdown', 'perspective_conversation'];
return styles.map((contentStyle) => {
  const payload = {
    contractVersion: '1.0',
    correlationId: request.correlationId,
    idempotencyKey: `rss-auto-drafts:${request.opportunityId}:${contentStyle}`,
    actorId: request.actorId,
    brandId: request.brandId,
    opportunityId: request.opportunityId,
    contentStyles: [contentStyle],
    tone: 'thoughtful',
    requestedAt: new Date().toISOString(),
  };
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
  const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
  const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
  return { json: { body, contentStyle, nonce, signature, timestamp, url: `${baseUrl}${path}` } };
});

const crypto = require('crypto');
const request = $('Signed Research Webhook').first().json.body;
const draftSets = $input.all().map((input) => input.json.data);
if (draftSets.length < 1 || draftSets.length > 3 || draftSets.some((draftSet) => draftSet?.contractVersion !== '1.0' || draftSet.opportunityId !== request.opportunityId || !Array.isArray(draftSet.drafts) || draftSet.drafts.length !== 1)) throw new Error('Editorial result contract is invalid');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.N8N_WEBHOOK_BASE_URL;
if (!secret || !baseUrl) throw new Error('Verification environment is not configured');
const path = '/webhook/post-verification-v1';
return draftSets.flatMap((draftSet) => draftSet.drafts).map((draft) => {
  if (!draft.postDraftId || !draft.postVersionId || draft.status !== 'ready_for_review') throw new Error('Generated draft contract is invalid');
  const payload = {
    contractVersion: '1.0',
    correlationId: request.correlationId,
    idempotencyKey: `rss-auto-verify:${draft.postDraftId}`,
    actorId: request.actorId,
    brandId: request.brandId,
    postDraftId: draft.postDraftId,
    requestedAt: new Date().toISOString(),
  };
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
  const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
  const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
  return { json: { actorId: request.actorId, brandId: request.brandId, correlationId: request.correlationId, expectedVersionId: draft.postVersionId, postDraftId: draft.postDraftId, body, nonce, signature, timestamp, url: `${baseUrl}${path}` } };
});

const crypto = require('crypto');
const verifications = $input.all();
const contexts = $('Sign Draft Verification Requests').all();
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.N8N_WEBHOOK_BASE_URL;
if (!secret || !baseUrl) throw new Error('Image preparation environment is not configured');
const path = '/webhook/image-generation-v1';
return verifications.flatMap((input, index) => {
  const verification = input.json.data;
  const context = contexts[index]?.json;
  if (!context || verification?.contractVersion !== '1.0' || verification.postDraftId !== context.postDraftId || !verification.postVersionId || !verification.evaluation || typeof verification.evaluation.readyForReview !== 'boolean') throw new Error('Verification result contract is invalid');
  if (!verification.evaluation.readyForReview) return [];
  const payload = {
    contractVersion: '1.0',
    correlationId: context.correlationId,
    idempotencyKey: `rss-auto-image:${context.postDraftId}`,
    actorId: context.actorId,
    brandId: context.brandId,
    postDraftId: context.postDraftId,
    expectedVersionId: verification.postVersionId,
    action: 'generate',
    imageStyle: 'editorial_hero',
    template: 'editorial_overlay',
    requestedAt: new Date().toISOString(),
  };
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
  const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
  const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
  return [{ json: { body, nonce, signature, timestamp, url: `${baseUrl}${path}` }, pairedItem: { item: index } }];
});
